INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 9, 'theory', 'Sockets in Your Program: Blocking I/O, select, epoll, and async');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 9, 0, 'What does accept() return on a listening socket?', '["A new socket for talking to the client that connected, and its address", "The data the client sent", "The port number", "Nothing: the connection is already accepted"]', 0, 'The listening socket stays and keeps accepting, while the conversation goes through the socket that accept returned.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 9, 1, 'The client called send three times, 100 bytes each. What will a single recv(4096) return on the server side?', '["Exactly the first 100 bytes", "Exactly 300 bytes", "Nothing until the connection is closed", "From 1 to 300 bytes: however much has piled up"]', 3, 'TCP is a stream of bytes with no message boundaries; recv returns what is there, but no more than requested.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 9, 2, 'What does an empty result (b'''') from recv mean?', '["A network error", "A timeout", "The other side closed the connection", "The data has not arrived yet"]', 2, 'End of stream: the other side closed the connection (FIN).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 9, 3, 'What advantage does epoll have over a thread per client?', '["No sockets are needed", "One thread serves many connections, and the cost depends on the number of ready sockets", "The data is encrypted", "Data is delivered faster over the network"]', 1, 'There are no hundreds of threads with stacks and context switches: the operating system itself tells you which sockets are ready.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 9, 4, 'Why shouldn''t heavy computation run directly inside an asyncio coroutine?', '["Coroutines cannot compute", "The result of the computation cannot be returned", "The computation stops the event loop, and all connections freeze", "The coroutine will close the socket"]', 2, 'The event loop runs in a single thread: while a coroutine computes without an await, everyone else waits.');
